import * as T from './three.module.js';
export function createGrainTrailer(){const root=new T.Group(),wheels=[],metal=new T.MeshStandardMaterial({color:'#60846a',metalness:.2,roughness:.6}),steel=new T.MeshStandardMaterial({color:'#78817f',metalness:.35,roughness:.55}),rubber=new T.MeshStandardMaterial({color:'#202925',roughness:.94});root.name='Open grain trailer with drawbar and tipping body';const unit=new T.BoxGeometry(1,1,1);function box(w,h,d,m,x,y,z){const o=new T.Mesh(unit,m);o.scale.set(w,h,d);o.position.set(x,y,z);root.add(o);return o;}
 box(2.2,.18,3.4,steel,0,.65,0);box(2.25,.15,3.5,metal,0,.87,0);for(const x of [-1.1,1.1]){box(.12,.9,3.5,metal,x,1.35,0);for(let z=-1.4;z<=1.4;z+=.7)box(.06,.95,.08,steel,x*1.06,1.35,z);}for(const z of [-1.7,1.7])box(2.25,.9,.12,metal,0,1.35,z);for(const x of [-.6,.6]){const bar=box(.1,.12,1.4,steel,x*.5,.58,2.1);bar.rotation.y=x>0?-.43:.43;}
 for(const x of [-1.25,1.25]){const pivot=new T.Group();pivot.position.set(x,.56,-.3);root.add(pivot);const tire=new T.Mesh(new T.CylinderGeometry(.56,.56,.38,16),rubber);tire.rotation.z=Math.PI/2;pivot.add(tire);const hub=new T.Mesh(new T.CylinderGeometry(.23,.23,.4,10),steel);hub.rotation.z=Math.PI/2;pivot.add(hub);wheels.push(pivot);}const grain=new T.Mesh(new T.BoxGeometry(2,.75,3.22),new T.MeshStandardMaterial({color:'#c0a363',roughness:1}));grain.position.set(0,1.25,0);root.add(grain);
 const tipping=new T.Group();tipping.name='Hydraulic tipping body';tipping.position.set(0,.8,-1.65);root.add(tipping);root.updateMatrixWorld(true);for(const o of [...root.children])if(o.isMesh&&o.position.y>=.8)tipping.attach(o);
 return {root,wheels,grain,tipping,update(tr,distance=0,preview=0,tip=0){tipping.rotation.x=-tip;root.visible=tr.owned;root.position.set(tr.x,.2,tr.z);root.rotation.y=tr.heading;const ratio=Math.max(0,Math.min(1,(tr.quantity+preview)/tr.capacity));grain.visible=ratio>0;grain.scale.y=ratio;grain.position.y=.18+.375*ratio;grain.material.color.set(tr.good==='feed'?'#b09865':'#d2b55b');for(const w of wheels)w.rotation.x+=distance/.56;}};
}
